import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { summarize, compareSamples } from './bench/lib/stats.mjs';
const receipt = JSON.parse(readFileSync('bench/c-first.json','utf8'));
assert.equal(receipt.status,'passed');
assert.equal(receipt.cases.length,46);
assert.equal(receipt.cases.reduce((n,c) => n+c.calls.length,0),143);
let metrics = 0, comparisons = 0;
function walk(value) {
  if (!value || typeof value !== 'object') return;
  if (value.unit && Array.isArray(value.samples)) {
    const checked = summarize(value.samples);
    for (const key of Object.keys(checked)) assert.equal(value[key],checked[key]);
    metrics++;
  }
  for (const child of Object.values(value)) walk(child);
}
walk(receipt);
for (const c of receipt.cases) {
  assert.deepEqual(c.compilation.comparison,compareSamples(c.compilation.wasm.emission.samples,c.compilation.c.total.samples));
  comparisons++;
  for (const call of c.calls) {
    const {c:native,wasm,upstream} = call.lanes;
    if (!call.comparisons) continue;
    assert.deepEqual(call.comparisons.cOverWasmFreshLifetime,compareSamples(wasm.freshLifetime.samples,native.freshLifetime.samples));
    assert.deepEqual(call.comparisons.cOverWasmProcess,compareSamples(wasm.process.metric.samples,native.process.metric.samples));
    comparisons+=2;
    if (upstream.status==='passed') {
      assert.deepEqual(call.comparisons.cOverUpstreamProcess,compareSamples(upstream.process.metric.samples,native.process.metric.samples));
      comparisons++;
    }
  }
}
console.log(JSON.stringify({metricSummariesVerified:metrics,bootstrapComparisonsVerified:comparisons}));
